import json, re
from pathlib import Path
s=json.loads(Path('.agents/skills/audit-intake-and-evidence-map/templates/audit-manifest.schema.json').read_text())
m=json.loads(Path('audit-manifest.json').read_text())
def check(v, rule):
 if '"'$ref'"' in rule:
  rule=s['"'$defs'"'][rule['"'$ref'"'].split('/')[-1]]
 t=rule.get('type')
 if t: assert isinstance(v, {'object':dict,'array':list,'string':str}[t])
 if 'enum' in rule: assert v in rule['enum']
 if 'pattern' in rule: assert re.search(rule['pattern'],v)
 if isinstance(v,dict):
  assert set(rule.get('required',[])) <= v.keys()
  for k,x in v.items():
   sub=rule.get('properties',{}).get(k,rule.get('additionalProperties',True))
   if isinstance(sub,dict): check(x,sub)
   else: assert sub is not False
 if isinstance(v,list) and 'items' in rule:
  for x in v: check(x,rule['items'])
check(m,s)
print('Validated all applicable constraints in the local manifest schema using a dependency-free checker.')
